#!/usr/bin/env python3
"""
Generate a test matrix from components.json for CI/CD systems.

Outputs a JSON matrix that can be consumed by GitHub Actions,
GitLab CI, or Jenkins to distribute tests across runners.
"""
import json
import sys
from pathlib import Path


def generate_matrix(components_file: Path) -> dict:
    """Create a sharded test matrix based on component count."""
    with open(components_file) as f:
        data = json.load(f)

    components = data.get("components", [])
    if not components:
        return {"include": [{"shard": 1, "components": []}]}

    # Group components into shards of max 5
    shard_size = 5
    shards = []
    for i in range(0, len(components), shard_size):
        shard_components = components[i:i + shard_size]
        shards.append({
            "shard": i // shard_size + 1,
            "components": [c["name"] for c in shard_components],
            "total_shards": (len(components) + shard_size - 1) // shard_size,
        })

    return {"include": shards}


if __name__ == "__main__":
    comp_file = Path(__file__).parent.parent / "components.json"
    matrix = generate_matrix(comp_file)
    print(json.dumps(matrix, indent=2))